INSERT INTO funding_schemes (id, name, provider, source_url, eligibility_summary, deadline_at, cycle, support_rate, match_rule, priority_note, template_key, status, provenance, legacy_id, visibility, created_at, updated_at) VALUES ('scheme-kmf', 'Kulturminnefondet – faste kulturminner', 'Kulturminnefondet', 'https://kulturminnefondet.no/sok-om-stotte/faste-kulturminner/', 'Restaurering og bevaring av verneverdige kulturminner. Svært relevant for gammel låve, mur og historiske konstruksjoner.', NULL, 'Løpende', 'Normalt ca. 30 %', 'Dugnad kan verdsettes til 350 kr/time', 'Høy prioritet', 'vern', 'unverified', 'legacy_mvp_2026_09_08', 'kmf', 'members', '2026-09-20T00:00:00.000Z', '2026-09-20T00:00:00.000Z') ON CONFLICT(id) DO UPDATE SET name = excluded.name, provider = excluded.provider, source_url = excluded.source_url, eligibility_summary = excluded.eligibility_summary, deadline_at = excluded.deadline_at, cycle = excluded.cycle, support_rate = excluded.support_rate, match_rule = excluded.match_rule, priority_note = excluded.priority_note, template_key = excluded.template_key, updated_at = excluded.updated_at, status = CASE WHEN funding_schemes.verified_at IS NULL THEN excluded.status ELSE funding_schemes.status END WHERE funding_schemes.provenance = 'legacy_mvp_2026_09_08';
INSERT INTO funding_schemes (id, name, provider, source_url, eligibility_summary, deadline_at, cycle, support_rate, match_rule, priority_note, template_key, status, provenance, legacy_id, visibility, created_at, updated_at) VALUES ('scheme-kmfsecure', 'Kulturminnefondet – sikringstiltak', 'Kulturminnefondet', 'https://kulturminnefondet.no/sok-om-stotte/sikringstiltak/', 'For akutte tiltak som hindrer videre skade eller tap av kulturminne.', NULL, 'Løpende', 'Prosjektavhengig', 'Dokumenter akutt skade og risiko', 'Vurder nå', 'secure', 'unverified', 'legacy_mvp_2026_09_08', 'kmfsecure', 'members', '2026-09-20T00:00:00.000Z', '2026-09-20T00:00:00.000Z') ON CONFLICT(id) DO UPDATE SET name = excluded.name, provider = excluded.provider, source_url = excluded.source_url, eligibility_summary = excluded.eligibility_summary, deadline_at = excluded.deadline_at, cycle = excluded.cycle, support_rate = excluded.support_rate, match_rule = excluded.match_rule, priority_note = excluded.priority_note, template_key = excluded.template_key, updated_at = excluded.updated_at, status = CASE WHEN funding_schemes.verified_at IS NULL THEN excluded.status ELSE funding_schemes.status END WHERE funding_schemes.provenance = 'legacy_mvp_2026_09_08';
INSERT INTO funding_schemes (id, name, provider, source_url, eligibility_summary, deadline_at, cycle, support_rate, match_rule, priority_note, template_key, status, provenance, legacy_id, visibility, created_at, updated_at) VALUES ('scheme-mrpre', 'Forhåndsundersøkelser av verneverdige byggverk', 'Møre og Romsdal fylkeskommune', 'https://mrfylke.no/tenester/tilskot-prisar-og-stipend/oversikt-over-tilskot-prisar-og-stipend/tilskot-til-forehandsundersokingar-av-verneverdige-byggverk.9238.aspx', 'For faglig dokumentasjon før restaurering. Ordningen prioriterer blant annet gårdsbygninger og enhetslåver.', NULL, 'Se utlysning', 'Vanligvis inntil 15 000 kr; større undersøkelser kan vurderes', 'Fylkesandel normalt maks 50 % for større tiltak', 'Sterk match', 'prestudy', 'unverified', 'legacy_mvp_2026_09_08', 'mrpre', 'members', '2026-09-20T00:00:00.000Z', '2026-09-20T00:00:00.000Z') ON CONFLICT(id) DO UPDATE SET name = excluded.name, provider = excluded.provider, source_url = excluded.source_url, eligibility_summary = excluded.eligibility_summary, deadline_at = excluded.deadline_at, cycle = excluded.cycle, support_rate = excluded.support_rate, match_rule = excluded.match_rule, priority_note = excluded.priority_note, template_key = excluded.template_key, updated_at = excluded.updated_at, status = CASE WHEN funding_schemes.verified_at IS NULL THEN excluded.status ELSE funding_schemes.status END WHERE funding_schemes.provenance = 'legacy_mvp_2026_09_08';
